def lps(s):
    n = len(s)
    dp = [0] * (n + 1)

    # Fill the DP table
    for i in range(2, n + 1):
        for j in range(i - 1, -1, -1):
            if s[j] == s[i - 1]:
                dp[i] = min(dp[j + 1], dp[i - 1]) + 2  # Add 2 because we can either include or exclude the character at index i-1
            else:
                dp[i] = max(dp[j], dp[i])

    return dp[n]
```

