def swap_count(s):
    # Initialize count of swaps and stack
    count = 0
    stack = []

    # Iterate through each character in the string
    for char in s:
        if char == '[':
            # Push opening brackets onto the stack
            stack.append(char)
        elif char == ']':
            # Pop from the stack until an opening bracket is found
            while stack and stack[-1] != '[':
                count += 1
                stack.pop()
            # If there's no matching opening bracket, return -1
            if not stack:
                return -1
            else:
                # Otherwise, pop the last element on the stack
                stack.pop()

    # Return the total number of swaps needed
    return count + len(stack)

